REM *************************** Resetting values for IDENTITY columns

Prompt ******  Resetting values for IDENTITY columns ....

ALTER TABLE categories MODIFY category_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
ALTER TABLE suppliers MODIFY supplier_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
ALTER TABLE customers MODIFY customer_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
ALTER TABLE stores MODIFY store_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
ALTER TABLE employees MODIFY employee_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
ALTER TABLE products MODIFY product_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
ALTER TABLE reviews MODIFY review_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
ALTER TABLE orders MODIFY order_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
ALTER TABLE shipments MODIFY shipment_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
ALTER TABLE inventory MODIFY inventory_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
ALTER TABLE payments MODIFY payment_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
